const items = $input.all()
const limit = $("/services").first().json.query.limit || 10

if (items.length === 0) {
  return {
    items: [],
    total: 0,
    total_pages: 0
  }
}

const total = parseInt(items[0].json.total_count) || 0;
const totalPages = Math.ceil(total / limit);

const cleanItems = items.map(item => {
  const { total_count, ...rest } = item.json;
  return rest;
});

return {
  items: cleanItems,
  total,
  total_pages: totalPages
};

// Payload público: este endpoint lo consume la landing /patient-login sin
// token. NUNCA agregar costos internos, categorías internas ni ids ajenos al
// servicio.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id != null && !r.error);

// Si la clínica no muestra precios, `price` y `currency` no se devuelven —
// omitirlos es más seguro que mandarlos y confiar en que la UI los esconda.
const showPricing = rows.length > 0 && rows[0].show_pricing === true;

const services = rows.map((s) => {
  const service = {
    id: String(s.id),
    name: s.name,
    description: s.description || null,
    duration_minutes: Number(s.duration_minutes) || 0,
    // La URL la arma el cliente a partir del id (la base del webhook es
    // configuración de entorno). Acá sólo se dice si vale la pena pedirla.
    has_image: s.has_image === true,
    image_updated_at: s.image_updated_at || null,
  };
  if (showPricing) {
    service.price = s.price == null ? null : Number(s.price);
    service.currency = s.currency || null;
  }
  // Redundantes —la consulta ya garantiza las dos cosas— pero explícitos:
  // dejan el payload legible cuando se inspecciona a mano y evitan que quien
  // lo consuma tenga que inferirlo.
  service.bookable_online = true;
  service.is_active = true;
  return service;
});

return [{ json: { statusCode: 200, body: services } }];

const assertServiceId = (value) => {
  const text = String(value ?? '').trim();
  if (!/^[0-9]+$/.test(text)) {
    throw new Error(`Invalid service_id: ${value}`);
  }
  return text;
};

const input = $input.first().json;
const body = input.body ?? input;
return [{ json: { service_id: assertServiceId(body.service_id) } }];

// El borrado en Drive es best-effort: la fila ya quedó limpia, que es lo que
// ve el usuario. Un archivo huérfano en Drive no justifica devolver un error.
const cleared = $('Limpiar en service_catalog').first().json;

if (!cleared || cleared.error || !cleared.id) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo quitar la imagen.' } } }];
}

return [{ json: { statusCode: 200, body: { success: true, service_id: cleared.id } } }];

const assertServiceId = (value) => {
  const text = String(value ?? '').trim();
  if (!/^[0-9]+$/.test(text)) {
    throw new Error(`Invalid service_id: ${value}`);
  }
  return text;
};

const input = $input.first().json;
const query = input.query ?? input;
return [{ json: { service_id: assertServiceId(query.service_id) } }];

const assertServiceId = (value) => {
  const text = String(value ?? '').trim();
  if (!/^[0-9]+$/.test(text)) {
    throw new Error(`Invalid service_id: ${value}`);
  }
  return text;
};

const item = $input.first();
const body = item.json.body ?? item.json ?? {};

const serviceId = assertServiceId(body.service_id);

// El archivo llega en la propiedad binaria `data` (el front hace
// formData.append('data', file), igual que el logo de clínica y la firma).
const binary = item.binary?.data0 || item.binary?.data;
if (!binary) throw new Error('image file is required (binary property "data")');

const allowed = ['image/png', 'image/jpeg', 'image/webp'];
if (!allowed.includes(binary.mimeType)) {
  throw new Error(`Unsupported image type: ${binary.mimeType}`);
}

// 1 MB, el mismo límite que valida el front.
if (binary.fileSize && Number(String(binary.fileSize).replace(/[^0-9]/g, '')) > 1024 * 1024) {
  throw new Error('Image file exceeds 1 MB');
}

const extension = binary.mimeType === 'image/webp' ? 'webp'
  : binary.mimeType === 'image/jpeg' ? 'jpg' : 'png';

return [{
  json: {
    service_id: serviceId,
    filename: binary.fileName || `service-${serviceId}.${extension}`,
    mimetype: binary.mimeType,
  },
  binary: item.binary,
}];

// El borrado del archivo anterior es best-effort: si falla, la imagen nueva ya
// quedó guardada y no hay razón para devolver un error al usuario.
const saved = $('Guardar en service_catalog').first().json;

if (!saved || saved.error || !saved.id) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo guardar la imagen.' } } }];
}

return [{ json: { statusCode: 200, body: {
  success: true,
  service_id: saved.id,
  filename: saved.image_filename,
  mimetype: saved.image_mimetype,
  image_updated_at: saved.image_updated_at,
} } }];

// Este flujo hace UNA sola cosa: prender o apagar `bookable_online`. No toca
// nombre, precio, duración ni nada más del servicio — de eso se encarga
// /catalogoservicios/upsert. Mantenerlo mínimo es el punto: es el único
// escritor de esa columna.
const input = $input.first().json;
const body = input.body ?? input;

const serviceId = String(body.service_id ?? '').trim();
if (!/^[0-9]+$/.test(serviceId)) {
  throw new Error(`Invalid service_id: ${body.service_id}`);
}

// Se exige un booleano explícito. Un valor ausente o raro NO se interpreta
// como `false`: apagar la agenda online de un servicio por un payload mal
// armado sería peor que rechazar la llamada.
const raw = body.bookable_online;
const isTrue = raw === true || raw === 'true';
const isFalse = raw === false || raw === 'false';
if (!isTrue && !isFalse) {
  throw new Error(`Invalid bookable_online: ${raw}`);
}

return [{ json: { service_id: serviceId, bookable_online: isTrue } }];

const row = $input.first().json;

if (!row || row.error || !row.id) {
  return [{ json: { statusCode: 404, body: { message: 'No se encontró el servicio.' } } }];
}

return [{ json: { statusCode: 200, body: {
  success: true,
  service_id: row.id,
  name: row.name,
  bookable_online: row.bookable_online === true,
} } }];

// Este flujo hace UNA sola cosa: marcar o desmarcar un servicio como trabajo de
// laboratorio (service_catalog.is_lab, script 167). Es el único escritor de esa
// columna: /catalogoservicios/upsert no la toca, así una edición que no la
// mande no la apaga.
const input = $input.first().json;
const body = input.body ?? input;

const serviceId = String(body.service_id ?? '').trim();
if (!/^[0-9]+$/.test(serviceId)) {
  throw new Error(`Invalid service_id: ${body.service_id}`);
}

// Se exige un booleano explícito: un valor ausente o raro no se toma como false.
const raw = body.is_lab;
const isTrue = raw === true || raw === 'true';
const isFalse = raw === false || raw === 'false';
if (!isTrue && !isFalse) {
  throw new Error(`Invalid is_lab: ${raw}`);
}

return [{ json: { service_id: serviceId, is_lab: isTrue } }];

const row = $input.first().json;

if (!row || row.error || !row.id) {
  return [{ json: { statusCode: row?.error ? 400 : 404, body: { message: row?.error ? 'No se pudo actualizar el servicio.' : 'No se encontró el servicio.' } } }];
}

return [{ json: { statusCode: 200, body: {
  success: true,
  service_id: row.id,
  name: row.name,
  is_lab: row.is_lab === true,
} } }];
